sed -i 's/val inputVerificationState = if(hasInputNode) PhoneKeyboardInputVerificationState.NODE_CREATED else PhoneKeyboardInputVerificationState.NOT_VERIFIED/val hasInputNode = inputDeviceRepository.hasInputDeviceFor(address)\n            val verificationFlow = inputDeviceRepository.getVerificationResult(address)\n            var isEventVerified = false\n            scope.launch { verificationFlow.collect { result -> isEventVerified = result?.success == true } }\n            val inputVerificationState = when { isEventVerified -> PhoneKeyboardInputVerificationState.EVENT_VERIFIED ; hasInputNode -> PhoneKeyboardInputVerificationState.NODE_CREATED; else -> PhoneKeyboardInputVerificationState.NOT_VERIFIED }/' app/src/main/java/com/cbkii/btandroidts/domain/phone_keyboard/PhoneKeyboardScanControllerImpl.kt
